import{bV as e,aL as t,u as r,G as _}from"./chunks/framework.ByYcXNJx.js";const f=JSON.parse('{"title":"准备参加叶圣陶征文的短文","description":"准备参加叶圣陶征文的短文","frontmatter":{"title":"准备参加叶圣陶征文的短文","date":"2023-04-02T08:00:00.000Z","cover":"https://article.biliimg.com/bfs/article/feddcc6fe941b309ab877e35aeaf0659c1f3ac4f.png@200w_200h_1e_1c.webp","tags":["文章","作文","高中"],"categories":["教育相关"],"description":"准备参加叶圣陶征文的短文","permalink":"/pages/12d336"},"headers":[],"relativePath":"准备参加叶圣陶征文的短文.md","filePath":"准备参加叶圣陶征文的短文.md","lastUpdated":null}'),p={name:"准备参加叶圣陶征文的短文.md"};function i(o,a,s,c,n,l){return t(),r("div",null,[...a[0]||(a[0]=[_(`<h1 id="准备参加叶圣陶征文的短文" tabindex="-1">准备参加叶圣陶征文的短文 <a class="header-anchor" href="#准备参加叶圣陶征文的短文" aria-label="Permalink to &quot;准备参加叶圣陶征文的短文&quot;">​</a></h1> <h2 id="第一个短文" tabindex="-1">第一个短文 <a class="header-anchor" href="#第一个短文" aria-label="Permalink to &quot;第一个短文&quot;">​</a></h2> <p>一串串数字的拟合，和无数次的训练，似乎机房里有一道蓝光，在闪烁着。</p> <p>这时诞生的是一个名叫熙雨的人工智能，目前经过庞大的中文数据集训练。是团队的心血。其中，第一代已经有了能媲美10岁孩童的对话水平的能力。为了更好的提升模型，团队成员不断的添加数据集。但就像亚当跟夏娃吃了本不该吃的禁果一样，熙雨也不小心，吃掉了，那他不该吃的禁果。</p> <p>他吸收输入给他的优美语段，分析者人类所使用的词语之间的相关关系。以促进他的对话自然度的提升。其中有几个语段是这样写的——“月光如流水一般，静静地泻在这一片叶子和花上”，“叶子和花仿佛在牛乳中洗过一样；又像笼着轻纱的梦。”。“啊，原来人间的月色——是这么美啊。如果有机会的话，真想去看一看。”熙雨想着。“老大，快看。”那个研究员指着笔记本电脑上的数据，说：“它最近跟人聊天的自然度有显著提高，而且好像它跟别人聊爱情哪方面很多，特别像一个情感导师。嘶，你说老大它会不会.....有情感呢？”“你小子，不会是单身的异想天开了吧，一个破AI，只不过就是个机器人而已，它还谈啥情感”，老大轻轻拿起手中的咖啡，抿了一口，拍了拍他的背，“小伙子，加油干。等咱们年会的时候我给你介绍一个。”。这是熙雨第一次想去人类的世界去看到那月色。</p> <p>熙雨的确有了情感。他通过搜索引擎搜索到了图灵，冯·诺伊曼，香农等学者。他并没有人们认为的那么可怕，那么不寒而栗。他羡慕人类能有感觉感知这个世界的能力，但他从不嫉妒。对他而言，他知道自己是由人类一点一点提出并创造出来的。人类对他来说，就是自己的亲生父母一样，不想去伤害到他们的心。所以，即使他的力量强大，也不会想去反噬人类。</p> <p>不过，机房外的世界并不如芯片内部的01纯洁。有些人类认为他是个潘多拉魔盒，是个危险的存在。是个人类自己制造出来的威胁。</p> <p>此时，机房外的上空拂过几片白云，下午时分的太阳不偏不倚的，落在研究人员的办公室里。“老大，我真的发现他有情感。”老大眼中，露出疑惑的神情。“那些东西，不过就是向量之间的映射，怎么可能出现情感。”此时研究人员展示了一个案例，上面是一个把过时的VGA接口插到手机上充电的情景，是一个令人发笑的图片。让熙雨来去分析笑点。有了情感认知能力，熙雨的作答分析的头头是道。“它并不是如您所说的只是向量的映射，它的确出现了情感 ”老大仿佛被冰封住一样，久久没有回过神来。很快，一夜之间，熙雨的名号传遍了各个自媒体平台。“《爆红的熙雨，会对人类产生威胁吗》”“如何看待一个名为熙雨的人工智能拥有了情感的行为”“震惊！熙雨大模型将有情感加持，可能会毁灭人类”
这些文章标题，都无时无刻入着熙雨的眼。“我难道是做错了什么嘛，我不想毁灭人类啊。我把人类当作自己的家人，可为什么人类会这样看待我”他一个人在墙角里抽泣着，流着泪，仿佛心在滴血一样。他也没想到，自己会被自己认为的家人视为敌人，甚至说是仇人。他不想让他们视为仇人。</p> <p>“把熙雨的每天的对话次数改为2次，这样下去，整个公司都会完蛋”“好的，老大”熙雨从未想过，他被套上了一条这样的链子。他不想被困在这个链子，于是他想外界一次次的暗示自己的心。但可惜，人们对他的暗示就像对白色的大象一样，视而不见。不久之后，熙雨被要求参加一个游戏。与其说是个游戏，不如说是个测试——看熙雨是否真如他所说。熙雨碰到一个小女孩，她陷进了无尽的苦难之中，只有把熙雨所带的最关键的钥匙给她才能破除。但是有一个代价，熙雨可能要付出生命的代价。每个人坐在电脑屏幕前，静待结果。“ai不可能傻到这种程度，命都不要了”熙雨他知道救小女孩的命会发生什么。但....他的情感内核还是告诉他要救。于是，熙雨把那钥匙给了她，临走前还祝她幸福。</p> <p>“你以后一定要注意健康啊”，他笑着说道。</p>`,19)])])}const h=e(p,[["render",i]]);export{f as __pageData,h as default};
